body:
there can input VAR ENV with function params:

```rust
/// Substitute parameters with custom variable resolver
fn substitute_params_with<F>(args: &[String], resolver: F) -> Vec<String>
where
    F: Fn(&str) -> Option<String>,
{
    let re = Regex::new(r"\$\{([^}]+)\}").unwrap();
    args.iter()
        .map(|arg| {
            re.replace_all(arg, |caps: &regex::Captures| {
                resolver(&caps[1]).unwrap_or_else(|| format!("${{{}}}", &caps[1]))
            })
            .to_string()
        })
        .collect()
}

/// Original function using std::env
fn substitute_params(args: &[String]) -> Vec<String> {
    substitute_params_with(args, |var| std::env::var(var).ok())
}

// The test can then be independent of environment variables.
#[test]
fn test_substitute_single_var() {
    let args = vec!["${TEST_VAR}".to_string()];
    let result = substitute_params_with(&args, |var| {
        if var == "TEST_VAR" {
            Some("value".to_string())
        } else {
            None
        }
    });
    assert_eq!(result, vec!["value"]);
}
