+        let new_snippet = crate::snippets::Snippet {
+            name: name.clone(),
+            args,
+            category,
+            description: desc,
+        };
+        match &mode {
+            SnippetEditMode::Create => {
+                if user_only.iter().any(|s| s.name == name) {
+                    self.set_error(format!("Snippet '{}' already exists", name));
+                    return;
+                }
+                user_only.push(new_snippet);
