+            SnippetCategory::Cpu,
+            SnippetCategory::Machine,
+            SnippetCategory::Storage,
+            SnippetCategory::Network,
+            SnippetCategory::Display,
+            SnippetCategory::Debug,
+            SnippetCategory::Kernel,
